import React from 'react';
import { Box, Typography, Button } from '@mui/material';
import { CalendarToday } from '@mui/icons-material'; // Calendar icon import edildi

function CustomCard({ title, description, tags, buttonText, imageUrl, eventdate, lastdate }) {
  return (
    <Box
      sx={{
        backgroundColor: '#F5F5F5', // Arkaplan rengi eklendi
        padding: '20px 0', // Genel padding
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
      }}
    >
      {/* Başlık */}
      <Typography
        variant="h5"
        sx={{
          fontWeight: 'bold',
          marginBottom: '20px',
          color: '#293349',
        }}
      >
        Başvurunu Bekleyen Etkinlikler
      </Typography>

      {/* Kart */}
      <Box
        sx={{
          width: '328px', // Sabit genişlik
          height: '519px', // Kartın toplam yüksekliği
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'flex-start', // İçeriği üstten başlatıyoruz
          alignItems: 'center',
          padding: '0',
          backgroundColor: '#FFFFFF',
          border: '1px solid #293349',
          borderRadius: '16px 16px 0 0', // Kartın üst köşeleri yuvarlatılmış
          boxSizing: 'border-box',
          margin: '10px',
          position: 'relative',
          overflow: 'hidden', // Kartın yuvarlak köşeleri dışına taşmayı engeller
        }}
      >
        {/* Banner Image */}
        <Box
          sx={{
            width: '328px', // Genişlik 328px
            height: '171px', // Yükseklik sabit 171px
            padding: '16px 0px 0px 0px', // Padding yalnızca üst taraftan 16px
            gap: '0px', // gap sıfırlandı
            backgroundImage: `url(${imageUrl})`, // Resim URL'si
            backgroundSize: 'cover', // Görselin kutuya sığacak şekilde boyutlandırılması
            backgroundPosition: 'center', // Görselin ortalanması
            position: 'relative',
            border: '1px solid rgba(216, 216, 216, 1)', // Figma'dan gelen border
          }}
        />

        {/* İçerik Alanı */}
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'flex-start',
            alignItems: 'center',
            padding: '16px',
            gap: '16px', // Flex gap'ini küçük tutarak öğeler arasındaki mesafeyi kontrol et
            width: '328px',
            height: '348px',
          }}
        >
          {/* Etiketler */}
          <Box
            sx={{
              paddingRight: '190px',
              width: '296px',
              gap: '8px',
              display: 'flex',
              flexDirection: 'row',
              justifyContent: 'center',
            }}
          >
            {tags.map((tag, index) => (
              <Box
                key={index}
                sx={{
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                  padding: '5px 10px',
                  width: '34px',
                  height: '22px',
                  border: '1px solid #293349',
                  borderRadius: '16px',
                }}
              >
                <Typography sx={{ fontSize: '12px', color: '#293349' }}>{tag}</Typography>
              </Box>
            ))}
          </Box>

          {/* Etkinlik Tarihi */}
          {eventdate && (
            <Box sx={{ width: '296px', display: 'flex', flexDirection: 'row', alignItems: 'center', gap: '4px' }}>
              <CalendarToday sx={{ color: '#1D1D1D', fontSize: '18px' }} /> {/* Calendar Icon */}
              <Typography sx={{ fontSize: '12px', color: '#1D1D1D' }}>{eventdate}</Typography> {/* Event Date */}
            </Box>
          )}

          {/* Başlık ve Açıklama */}
          <Box
            sx={{
              width: '296px',
              gap: '16px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'flex-start',
            }}
          >
            <Typography
              variant="h6"
              sx={{
                fontWeight: '500',
                fontSize: '20px',
                color: '#1D1D1D',
              }}
            >
              {title}
            </Typography>
            <Typography sx={{ fontSize: '16px', color: '#878787' }}>{description}</Typography>
          </Box>

          {/* Son Başvuru Tarihi */}
          <Box
            sx={{
              width: '296px',
              display: 'flex',
              flexDirection: 'row',
              alignItems: 'center',
              gap: '4px',
            }}
          >
            <p>Son Başvuru Tarihi</p>
            <Typography sx={{ paddingLeft: '15px', fontSize: '16px', color: '#1D1D1D' }}>
              {lastdate}
            </Typography>
          </Box>

          {/* Buton */}
          <Box
            sx={{
              width: '296px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: '8px',
            }}
          >
            <Button
              variant="contained"
              sx={{
                backgroundColor: '#00C26D',
                borderRadius: '4px',
                padding: '4px 52px',
                color: '#FFFFFF',
              }}
            >
              {buttonText}
            </Button>
          </Box>
        </Box>
      </Box>
    </Box>
  );
}

export default CustomCard;
